const indexes={en:1,de:2,ar:3} as const;
const catalogs={
 en:new Map(rows.map(row=>[row[0].trim(),row[1].trim()])),
 de:new Map(rows.map(row=>[row[0].trim(),row[2].trim()])),
 ar:new Map(rows.map(row=>[row[0].trim(),row[3].trim()]))
};
const fallbackPhrases=[...new Set(rows.map(row=>row[0].trim()).filter(phrase=>phrase.length>=4))].sort((a,b)=>b.length-a.length);

let runtimeLanguage:Language='tr';

export function isLanguage(value:unknown):value is Language{return typeof value==='string'&&languageOptions.some(option=>option.code===value);}
export function readStoredLanguage():Language{try{const value=localStorage.getItem(LANGUAGE_STORAGE_KEY);return isLanguage(value)?value:'tr';}catch{return 'tr';}}
export function setRuntimeLanguage(language:Language){runtimeLanguage=language;}
export function currentLanguage(){return runtimeLanguage;}
export function localeFor(language:Language=runtimeLanguage){return language==='ar'?'ar-SY':language==='en'?'en-GB':language==='de'?'de-DE':'tr-TR';}
export function directionFor(language:Language=runtimeLanguage):'ltr'|'rtl'{return language==='ar'?'rtl':'ltr';}

function withDynamicParts(source:string,language:Exclude<Language,'tr'>){
 let value=source;
 const catalog=catalogs[language];
 for(const phrase of fallbackPhrases){
  if(!value.includes(phrase))continue;
  value=value.split(phrase).join(catalog.get(phrase)??phrase);
 }
 return value;
}

export function translate(source:string,language:Language=runtimeLanguage):string{
 if(language==='tr'||!source)return source;
 const core=source.trim();if(!core)return source;
 const leading=source.slice(0,source.indexOf(core)),trailing=source.slice(source.indexOf(core)+core.length);
 const exact=catalogs[language].get(core);
 if(exact)return leading+exact+trailing;
 const version=core.match(/^Sürüm\s+(.+)$/);if(version)return leading+catalogs[language].get('Sürüm')+' '+version[1]+trailing;
 const translated=withDynamicParts(core,language);
 return leading+translated+trailing;
}

export const t=translate;

export function translatedKeys(language:Exclude<Language,'tr'>){return new Set(rows.filter(row=>Boolean(row[indexes[language]])).map(row=>row[0].trim()));}
